Assembly Code Example<sup>(1)</sup> 

```
USART_Init:
; Set baud rate
outUBRRHn, r17
outUBRRLn, r16
; Enable receiver and transmitter
ldir16, (1<<RXENn)|(1<<TXENn)
outUCSRnB,r16
; Set frame format: 8data, 2stop bit
ldir16, (1<<USBSn)|(3<<UCSZn0)
outUCSRnC,r16
